import {
  Card,
  Container,
  IconButton,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TablePagination,
  TableRow,
  Typography,
  TextField,
  Button,
  Box,
  MenuItem,
  Select,
  FormControl,
  InputLabel,
  Alert
} from '@mui/material';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { sentenceCase } from 'change-case';
import { enqueueSnackbar } from 'notistack';
import { useEffect, useState } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate } from 'react-router-dom';
import Iconify from '../../components/iconify'; // Ensure this import is correct
import Label from '../../components/label';
import Scrollbar from '../../components/scrollbar';
import AuthService from '../../services/AuthService';
import HttpService from '../../services/HttpService';
import TransactionListHead from './TransactionListHead';

const TABLE_HEAD = [
  { id: 'id', label: 'Id', alignRight: false, firstColumn: true },
  { id: 'fromWallet', label: 'Sender', alignRight: false },
  { id: 'toWallet', label: 'Receiver', alignRight: false },
  { id: 'amount', label: 'Amount', alignRight: true },
  { id: 'category', label: 'Category', alignRight: false },
  { id: 'subcategory', label: 'Subcategory', alignRight: false },
  { id: 'description', label: 'Description', alignRight: false },
  { id: 'createdAt', label: 'Time of Transaction', alignRight: false },
  { id: 'type', label: 'Type', alignRight: false },
  { id: 'status', label: 'Status', alignRight: false },
  { id: '' },
];

const CATEGORIES = {
  'Food & Dining': ['Groceries', 'Restaurants', 'Fast Food'],
  'Transportation': ['Public Transit', 'Fuel', 'Car Maintenance'],
  'Shopping': ['Clothing', 'Electronics', 'Home Goods'],
  'Bills & Utilities': ['Electricity', 'Water', 'Internet'],
  'Healthcare': ['Doctor', 'Pharmacy', 'Insurance'],
  'Entertainment': ['Movies', 'Games', 'Sports'],
};

export default function Transaction() {
  const [open, setOpen] = useState(null);
  const [page, setPage] = useState(0);
  const [selected, setSelected] = useState([]);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [data, setData] = useState([]);
  const navigate = useNavigate();

  // New states for enhanced features
  const [startDate, setStartDate] = useState(null);
  const [endDate, setEndDate] = useState(null);
  const [budget, setBudget] = useState('');
  const [monthlySpent, setMonthlySpent] = useState(0);
  const [selectedCategory, setSelectedCategory] = useState('');
  const [selectedSubcategory, setSelectedSubcategory] = useState('');
  const [categoryStats, setCategoryStats] = useState([]);

  useEffect(() => {
    fetchData();
  }, []); // Fetch data only once on component mount

  useEffect(() => {
    calculateMonthlySpent();
    generateCategoryStats();
  }, [data, budget]); // Recalculate when data or budget changes

  const handleOpenMenu = (event) => {
    setOpen(event.currentTarget);
  };

  const handleCloseMenu = () => {
    setOpen(null);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(0);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleCategoryChange = (event) => {
    setSelectedCategory(event.target.value);
    setSelectedSubcategory('');
  };

  const handleSubcategoryChange = (event) => {
    setSelectedSubcategory(event.target.value);
  };

  const handleBudgetChange = (event) => {
    const newBudget = event.target.value;
    setBudget(newBudget);
    checkBudgetExceed(monthlySpent, newBudget);
  };

  const checkBudgetExceed = (spent, budgetLimit) => {
    if (budgetLimit && spent > Number(budgetLimit)) {
      enqueueSnackbar('Warning: Monthly spending has exceeded budget!', { 
        variant: 'warning',
        autoHideDuration: 5000,
      });
    }
  };

  const calculateMonthlySpent = () => {
    const currentMonth = new Date().getMonth();
    const currentYear = new Date().getFullYear();

    const monthlyTransactions = data.filter(transaction => {
      const transDate = new Date(transaction.createdAt);
      return transDate.getMonth() === currentMonth && 
             transDate.getFullYear() === currentYear;
    });

    const total = monthlyTransactions.reduce((sum, transaction) => 
      sum + Number(transaction.amount), 0
    );

    setMonthlySpent(total);
    if (budget) {
      checkBudgetExceed(total, budget);
    }
  };

  const generateCategoryStats = () => {
    const stats = Object.keys(CATEGORIES).map(category => ({
      name: category,
      amount: data
        .filter(t => t.category === category)
        .reduce((sum, t) => sum + Number(t.amount), 0)
    }));
    setCategoryStats(stats);
  };

  const handleGenerateReport = () => {
    if (!startDate || !endDate) {
      enqueueSnackbar('Please select both start and end dates', { variant: 'warning' });
      return;
    }

    const userId = AuthService.getCurrentUser()?.id;
    HttpService.getWithAuth(
      `/transactions/users/${userId}?startDate=${startDate.toISOString()}&endDate=${endDate.toISOString()}`
    )
      .then((response) => {
        setData(response.data.content);
        generateCategoryStats();
      })
      .catch((error) => handleError(error));
  };

  const fetchData = () => {
    const userId = AuthService.getCurrentUser()?.id;
    HttpService.getWithAuth(`/transactions/users/${userId}`)
      .then((response) => {
        setData(response.data.content);
      })
      .catch((error) => handleError(error));
  };

  const handleError = (error) => {
    if (error?.response?.status === 401) {
      navigate('/login');
    } else if (error.response?.data?.errors) {
      error.response?.data?.errors.map((e) => enqueueSnackbar(e.message, { variant: 'error' }));
    } else if (error.response?.data?.message) {
      enqueueSnackbar(error.response?.data?.message, { variant: 'error' });
    } else {
      enqueueSnackbar(error.message, { variant: 'error' });
    }
  };

  const emptyRows = page > 0 ? Math.max(0, (1 + page) * rowsPerPage - data.length) : 0;

  return (
    <LocalizationProvider dateAdapter={AdapterDateFns}>
      <Helmet>
        <title> Transactions | e-Transaction </title>
      </Helmet>
      <Container sx={{ minWidth: '100%' }}>
        {/* Budget, Report, Category, and Transaction Table JSX code here... */}
      </Container>
    </LocalizationProvider>
  );
}
